<template>
  <div class="applInfo">
    <div class="applName" v-for="(item, index) in appList" :key="index" @mouseenter="prefetchApp(item)" @click="goPage(item)">
      <div class="imgCtr">
        <div class="imgContent">
          <a-image
            :preview="false"
            :src="item?.icon"
            style="width: 100%; height: 100%"
            fallback="data:image/png;base64,"
          />
        </div>
      </div>
      <div class="name">{{ item.name }}</div>
    </div>
  </div>
</template>
<script>
import { defineComponent, ref } from "vue";

import { useChildApplication } from "@/hooks/use-child-application";
import { prefetchApplication } from "@/utils/micro-app-prefetch";

export default defineComponent({
  props: {
    appList: {
      type: Array,
      default: () => {
        return [];
      },
    },
  },
  setup() {
    const childApplication = useChildApplication();
    const goPage = (item) => {
      if (item.url) {
        window.open(item.url);
        return;
      }
      childApplication.toChildApplication(item);
    };
    const prefetchApp = (item) => {
      prefetchApplication(item);
    };

    return {
      goPage,
      prefetchApp,
    };
  },
});
</script>
